def transform(g):
    H,W=len(g),len(g[0])
    comps=components(g)
    from collections import OrderedDict
    groups=OrderedDict(); bottom_row={}
    for col,cells in comps:
        groups.setdefault(col,[]).append(norm(cells))
        bottom_row[col]=max(bottom_row.get(col,-1), max(r for r,_ in cells))
    order=sorted(groups, key=lambda c: bottom_row[c])  # color whose lowest cell is highest goes left
    out=[[0]*W for _ in range(H)]
    x=0
    for col in order:
        shapes=sorted(groups[col], key=lambda m: len(m[0]))  # width asc, stable
        Wcol=max(len(m[0]) for m in shapes)
        placements=[None]*len(shapes); bottom=H-1
        for i in range(len(shapes)-1,-1,-1):
            m=shapes[i]; h=len(m)
            placements[i]=bottom-h+1; bottom-=h
            if i>0 and (len(shapes[i-1])>=2 or len(shapes[i])>=2):
                bottom-=1
        for i,m in enumerate(shapes):
            for r in range(len(m)):
                for c in range(len(m[0])):
                    if m[r][c]: out[placements[i]+r][x+c]=col
        x+=Wcol+1
    return out

